import { createContext, useContext, useState } from "react";
import { View, Text, Pressable, useColorScheme } from "react-native";

// Token theo VAI TRÒ (nền, chữ), không theo màu cụ thể: đổi chủ đề chỉ đổi bảng này
const themes = {
  light: { bg: "#ffffff", text: "#0f172a", accent: "#0ea5e9" },
  dark:  { bg: "#0f172a", text: "#f1f5f9", accent: "#38bdf8" },
};
const ThemeCtx = createContext(themes.light);
const useTheme = () => useContext(ThemeCtx);

function Card() {
  const t = useTheme();
  return <View testID="card" style={{ backgroundColor: t.bg, padding: 16 }}><Text style={{ color: t.text }}>Chào</Text></View>;
}

export default function App() {
  const system = useColorScheme() ?? "light";          // theo hệ điều hành
  const [override, setOverride] = useState(null);       // người dùng có thể chọn riêng
  const scheme = override ?? system;
  return (
    <ThemeCtx.Provider value={themes[scheme]}>
      <Card />
      <Pressable testID="toggle" onPress={() => setOverride(scheme === "dark" ? "light" : "dark")}><Text>Đổi chủ đề</Text></Pressable>
    </ThemeCtx.Provider>
  );
}

